const I18N = {};

let lang = localStorage.getItem("mimicLang") || "";

if(!lang){

    /* on part de la langue du telephone si on la connait */
    const nav = (navigator.language || "fr").toLowerCase();

    const guess = nav.startsWith("zh")
        ? (/(tw|hk|hant)/.test(nav) ? "zt" : "zh")
        : nav.slice(0, 2);

    lang = LANGS.some(l => l.id === guess) ? guess : "fr";

}


/* le texte francais d'origine, releve une seule fois */
const I18N_FR = {};


function i18nCollect(){

    document.querySelectorAll("[data-i18n]").forEach(el => {

        const k = el.getAttribute("data-i18n");

        if(!(k in I18N_FR)){
            I18N_FR[k] = el.textContent;
        }

    });

    /* les invites de saisie se traduisent aussi */
    document.querySelectorAll("[data-i18n-ph]").forEach(el => {

        const k = el.getAttribute("data-i18n-ph");

        if(!(k in I18N_FR)){
            I18N_FR[k] = el.getAttribute("placeholder") || "";
        }

    });

}


function T(key){

    const i = I18N_KEYS.indexOf(key);
    const a = I18N[lang];

    if(a && i >= 0 && a[i]){
        return a[i];
    }

    if(key in I18N_FR){
        return I18N_FR[key];
    }

    /* cles utilisees seulement depuis le code */
    return I18N_FR_EXTRA[key] || key;

}


function applyLang(){

    document.querySelectorAll("[data-i18n]").forEach(el => {
        el.textContent = T(el.getAttribute("data-i18n"));
    });

    document.querySelectorAll("[data-i18n-ph]").forEach(el => {
        el.setAttribute("placeholder", T(el.getAttribute("data-i18n-ph")));
    });

    const l = LANGS.find(x => x.id === lang) || LANGS[0];

    document.documentElement.lang = l.id;
    document.documentElement.dir  = l.rtl ? "rtl" : "ltr";

    /* les ecrans qui se redessinent tout seuls */
    if(typeof lobbySetMode === "function"){
        lobbySetMode(
            typeof lobbyMode === "string" && lobbyModeList().indexOf(lobbyMode) >= 0
                ? lobbyMode
                : "solo"
        );
    }

    if(typeof lobbySyncSkin === "function"){
        lobbySyncSkin();
    }

    if(typeof renderShop === "function" &&
       document.getElementById("shop").style.display === "block"){
        renderShop();
    }

    if(typeof paintLangGrid === "function"){
        paintLangGrid();
    }

}


function setLang(id){

    lang = id;

    try{ localStorage.setItem("mimicLang", id); }catch(e){}

    applyLang();

    paintLangGrid();

}


function paintLangGrid(){

    ["langGrid", "helloLangGrid"].forEach(id => paintOneLangGrid(id));

}


function paintOneLangGrid(id){

    const grid = document.getElementById(id);

    if(!grid){
        return;
    }

    grid.innerHTML = "";

    LANGS.forEach(l => {

        const b = document.createElement("button");

        b.className = "langBtn" + (l.id === lang ? " on" : "");
        b.innerHTML = "<span>" + l.flag + "</span>" + l.name;

        b.onclick = () => {
            setLang(l.id);
            sound(700, .06, "sine", .03);
        };

        grid.appendChild(b);

    });

}


